#!/usr/bin/env python3
"""
Minimal agentic loop using Anthropic API with bash tool and human confirmation.
"""

import os
import sys
import subprocess
import json
from typing import Dict, Any, List, Optional
from anthropic import Anthropic


class BashTool:
    """Tool for executing bash commands with user confirmation."""

    def __init__(self):
        self.name = "run_bash"
        self.description = "Execute a bash command"

    def execute(self, command: str) -> Dict[str, Any]:
        """Execute a bash command after user confirmation."""
        print(f"\n🔧 Tool Request: {self.name}")
        print(f"📝 Command: {command}")

        # Get user confirmation
        while True:
            response = input("\nExecute this command? (y/n): ").lower().strip()
            if response == 'y':
                break
            elif response == 'n':
                return {
                    "success": False,
                    "output": "Command execution cancelled by user",
                    "error": None
                }

        try:
            # Execute the command
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )

            return {
                "success": result.returncode == 0,
                "output": result.stdout,
                "error": result.stderr if result.stderr else None,
                "exit_code": result.returncode
            }
        except subprocess.TimeoutExpired:
            return {
                "success": False,
                "output": "",
                "error": "Command timed out after 30 seconds"
            }
        except Exception as e:
            return {
                "success": False,
                "output": "",
                "error": str(e)
            }


class AgentLoop:
    """Minimal agentic loop with Anthropic API."""

    def __init__(self, api_key: Optional[str] = None):
        self.client = Anthropic(api_key=api_key or os.getenv("ANTHROPIC_API_KEY"))
        self.tools = {
            "run_bash": BashTool()
        }
        self.conversation_history = []

    def get_tool_definitions(self) -> List[Dict[str, Any]]:
        """Get tool definitions for the API."""
        return [{
            "name": "run_bash",
            "description": "Execute a bash command",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        }]

    def process_tool_calls(self, tool_use_blocks: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process tool calls from the assistant."""
        results = []

        for block in tool_use_blocks:
            if block["type"] == "tool_use":
                tool_name = block["name"]
                tool_input = block["input"]
                tool_id = block["id"]

                if tool_name in self.tools:
                    tool = self.tools[tool_name]
                    result = tool.execute(**tool_input)

                    results.append({
                        "type": "tool_result",
                        "tool_use_id": tool_id,
                        "content": json.dumps(result)
                    })
                else:
                    results.append({
                        "type": "tool_result",
                        "tool_use_id": tool_id,
                        "content": json.dumps({"error": f"Unknown tool: {tool_name}"})
                    })

        return results

    def run(self):
        """Run the main agent loop."""
        print("🤖 Anthropic Agent Loop Started")
        print("Type 'exit' or 'quit' to stop, or Ctrl+C\n")

        while True:
            try:
                # Get user input
                user_input = input("\n👤 You: ").strip()

                if user_input.lower() in ['exit', 'quit']:
                    print("\n👋 Goodbye!")
                    break

                if not user_input:
                    continue

                # Add user message to history
                self.conversation_history.append({
                    "role": "user",
                    "content": user_input
                })

                # Send to API with tools
                print("\n🤔 Thinking...")

                while True:
                    response = self.client.messages.create(
                        model="claude-3-5-sonnet-20241022",
                        max_tokens=4096,
                        messages=self.conversation_history,
                        tools=self.get_tool_definitions()
                    )

                    # Add assistant response to history
                    assistant_content = []
                    tool_use_blocks = []

                    for block in response.content:
                        if block.type == "text":
                            assistant_content.append({
                                "type": "text",
                                "text": block.text
                            })
                            print(f"\n🤖 Assistant: {block.text}")
                        elif block.type == "tool_use":
                            tool_use_blocks.append({
                                "type": "tool_use",
                                "id": block.id,
                                "name": block.name,
                                "input": block.input
                            })
                            assistant_content.append({
                                "type": "tool_use",
                                "id": block.id,
                                "name": block.name,
                                "input": block.input
                            })

                    self.conversation_history.append({
                        "role": "assistant",
                        "content": assistant_content
                    })

                    # Process tool calls if any
                    if tool_use_blocks:
                        tool_results = self.process_tool_calls(tool_use_blocks)

                        # Add tool results to history
                        self.conversation_history.append({
                            "role": "user",
                            "content": tool_results
                        })

                        # Continue the loop to get the next response
                        continue
                    else:
                        # No tool calls, break the loop
                        break

            except KeyboardInterrupt:
                print("\n\n👋 Goodbye!")
                break
            except Exception as e:
                print(f"\n❌ Error: {str(e)}")
                # Remove the last user message if there was an error
                if self.conversation_history and self.conversation_history[-1]["role"] == "user":
                    self.conversation_history.pop()


def main():
    """Main entry point."""
    # Check for API key
    if not os.getenv("ANTHROPIC_API_KEY"):
        print("❌ Error: ANTHROPIC_API_KEY environment variable not set")
        print("Please set it with: export ANTHROPIC_API_KEY='your-api-key'")
        sys.exit(1)

    # Create and run the agent loop
    agent = AgentLoop()
    agent.run()


if __name__ == "__main__":
    main()

